"""Extract factual cmap/hmtx advances; do not copy font bytes or outlines."""

import argparse
import hashlib
import json
from pathlib import Path
import subprocess

from fontTools.ttLib import TTFont


ROOT = Path(__file__).resolve().parents[1]


def generate(font_dir):
    source = [
        "//! Verified Nimbus Roman SFNT advances, not glyph outlines or fallback ratios.",
        "//! Generated by scripts/extract_nimbus_roman_metrics.py.",
        "//! Source identities: data/font-metrics/nimbus-roman/source.json.",
        "use super::{FontMetric, LatinRange};",
    ]
    entries, evidence = [], []
    for index, (style, bold, italic) in enumerate([
        ("Regular", False, False), ("Bold", True, False),
        ("Italic", False, True), ("BoldItalic", True, True),
    ]):
        path = font_dir / f"NimbusRoman-{style}.otf"
        with TTFont(path) as font:
            family = font["name"].getDebugName(1)
            subfamily = font["name"].getDebugName(2)
            postscript = font["name"].getDebugName(6)
            assert family == "Nimbus Roman", family
            assert bool(font["head"].macStyle & 1) == bold
            assert bool(font["head"].macStyle & 2) == italic
            cmap = font.getBestCmap()
            widths = {code: font["hmtx"][glyph][0] for code, glyph in cmap.items()
                      if font.getGlyphID(glyph) != 0}
            assert all(0 < width <= 65535 for width in widths.values())
            aliases = sorted({family, postscript, f"{family} {subfamily}"})
            digest = hashlib.sha256(path.read_bytes()).hexdigest()
            evidence.append({"file": path.name, "sha256": digest, "family": family,
                             "subfamily": subfamily, "postscript": postscript,
                             "aliases": aliases, "bold": bold, "italic": italic,
                             "em": font["head"].unitsPerEm, "glyphs": len(widths),
                             "sourceTables": ["name", "head", "cmap", "hmtx"]})
            source.append(f"// {path.name} SHA-256 {digest}")
            ranges = []
            for code, width in sorted(widths.items()):
                if not ranges or code != ranges[-1][0] + len(ranges[-1][1]):
                    ranges.append((code, []))
                ranges[-1][1].append(width)
            for number, (start, values) in enumerate(ranges):
                source += [f"static W_{index}_{number}: [u16; {len(values)}] = [",
                           ", ".join(map(str, values)) + ",", "];"]
            source.append(f"static R_{index}: [LatinRange; {len(ranges)}] = [")
            for number, (start, values) in enumerate(ranges):
                source.append(f"LatinRange {{ start: {start}, end: {start + len(values) - 1}, widths: &W_{index}_{number} }},")
            source.append("];")
            for alias in aliases:
                entries.append(f"FontMetric {{ name: {json.dumps(alias)}, bold: {str(bold).lower()}, italic: {str(italic).lower()}, em_size: {font['head'].unitsPerEm}, latin_ranges: &R_{index}, hangul: None }},")
    source += [f"pub(super) static METRICS: [FontMetric; {len(entries)}] = [", *entries, "];", ""]
    return "\n".join(source), evidence


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--font-dir", required=True, type=Path)
    args = parser.parse_args()
    source, evidence = generate(args.font_dir)
    output = ROOT / "src/renderer/font_metric_nimbus_roman.rs"
    output.write_text(source)
    subprocess.run(["rustfmt", str(output)], check=True)
    dest = ROOT / "data/font-metrics/nimbus-roman/source.json"
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(json.dumps({"generator": "scripts/extract_nimbus_roman_metrics.py",
                               "source": "https://github.com/ArtifexSoftware/urw-base35-fonts",
                               "fontBytesOrOutlinesIncluded": False, "programs": evidence}, indent=2) + "\n")


if __name__ == "__main__":
    main()
